from typing import List

def sieve_of_eratosthenes(limit: int) -> List[bool]:
    """Generate a boolean list for primes up to limit using Sieve of Eratosthenes."""
    if limit < 2:
        return [False] * (limit + 1)

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(math.sqrt(limit)) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False

    return is_prime

def generate_primes_in_range(m: int, n: int) -> List[int]:
    """Generate all prime numbers in the range [m, n] efficiently."""
    # Since n can be up to 1e9, we can't use a sieve up to n
    # But we know that n - m <= 100000, so we can generate primes up to sqrt(n)
    # and then use that to check if numbers in [m, n] are prime

    # First, find all primes up to sqrt(n)
    sqrt_n = int(math.isqrt(n)) + 1
    small_primes = sieve_of_eratosthenes(sqrt_n)

    # Function to check if a number is prime using small primes
    def is_prime_num(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False

        # Check divisibility by odd primes up to sqrt(num)
        for i in range(3, int(math.isqrt(num)) + 1, 2):
            if small_primes[i] and num % i == 0:
                return False
        return True

    # Generate primes in [m, n]
    primes = []
    for num in range(m, n + 1):
        if num >= 2 and is_prime_num(num):
            primes.append(num)

    return primes

